 let h=H.sec('',`<div class="card pad lv-inv"><div style="display:flex;gap:14px;align-items:center"><div style="width:96px;flex:none">${H.qr(t('Tax invoice QR (sample)','رمز الفاتورة الضريبية (تجريبي)'),no.length+Math.round(amt))}</div><div style="flex:1;min-width:0">${H.kv([[t('Invoice','الفاتورة'),LTR(no)],[t('Issued','الإصدار'),dt(i.d,{day:'numeric',month:'short',year:'numeric'})],[t('Due','الاستحقاق'),dt(i.due,{day:'numeric',month:'short',year:'numeric'})]])}</div></div></div>`,{raw:true});
 if(o){ const T=tot(o); h+=H.sec(t('Lines','البنود'),Object.entries(o.items).map(([k,q])=>H.row({g:P0()[k].g,t:pn(k),s:`${q} × ${M(P0()[k].pr)}`,end:M(P0()[k].pr*q)})).join(''))+H.sec('',H.kv([[t('Subtotal','المجموع الفرعي'),M(T.sub)],T.disc?[t('Discount','الخصم'),M(-T.disc)]:null,T.fee?[t('Delivery','التوصيل'),M(T.fee)]:null,[t('VAT 15%','الضريبة 15%'),M(T.vat)],[t('Total','الإجمالي'),M(amt),'tot']])); }
 else h+=H.sec('',H.kv([[t('Total incl. VAT','الإجمالي شامل الضريبة'),M(amt),'tot']]));
 h+=H.sec(t('Balance','الرصيد'),H.kv([[t('Paid','المدفوع'),M(i.paid||0)],i.cr?[t('Credit notes','الإشعارات الدائنة'),M(-i.cr)]:null,[t('Balance due','المتبقي'),M(b),'tot']]));
