L.def('b.pay',{v:null,noSeg:true,render:(c)=>{ const s=S(); const pre=qp('no'); const due=s.invoices.filter(i=>bal(i)>0).sort((a,b)=>a.due-b.due);
 if(!due.length) return H.empty('ok',t('Nothing to pay','لا شيء للدفع'),t('All invoices are paid.','كل الفواتير مدفوعة.'),H.btns(H.btn(t('Finance','المالية'),{go:'b.finance'})));
 L.ui.paySel=L.ui.paySel||{}; const sk=k=>k!=='__pre';
 if(pre&&L.ui.paySel.__pre!==pre){ L.ui.paySel={__pre:pre}; L.ui.paySel[pre]=true; }
 if(!Object.keys(L.ui.paySel).filter(sk).length){ due.forEach(i=>{ if(i.due<now()) L.ui.paySel[i.no]=true; }); if(!Object.keys(L.ui.paySel).filter(sk).length) L.ui.paySel[due[0].no]=true; }
 const sel=due.filter(i=>L.ui.paySel[i.no]); const amt=r2(sel.reduce((a,i)=>a+bal(i),0)); L.ui.payM=L.ui.payM||'card';
 let h=H.sec(t('Choose invoices','اختر الفواتير'),due.map(i=>{ const id='pi'+i.no; return `<div class="row tog"><input class="cb" type="checkbox" id="${id}" data-act="paysel" data-arg="${i.no}"${L.ui.paySel[i.no]?' checked':''}><span class="b"><label class="t" for="${id}">${LTR(i.no)}</label><span class="s">${i.due<now()?H.pill('bad',t('Overdue','متأخرة')):t('Due','يستحق')+' '+dt(i.due)}</span></span><span class="e">${M(bal(i))}</span></div>`; }).join(''));
 h+=H.sec(t('Pay with','الدفع بواسطة'),L.radio('paym',[['card',t('Card, mada or Apple Pay','بطاقة أو مدى أو Apple Pay'),t('Instant · simulated','فوري · محاكى')],['sadad',t('SADAD','سداد'),t('Bill number shown after confirming (sample)','يظهر رقم الفاتورة بعد التأكيد (تجريبي)')],['transfer',t('Bank transfer','تحويل بنكي'),t('Marked paid when received (instant in this demo)','تُعلّم مدفوعة عند الاستلام (فوري في العرض)')]],L.ui.payM,t('Payment method','طريقة الدفع')));
 return {b:h,dock:`<div class="dt"><small>${t(`${sel.length} selected`,`${sel.length} محددة`)}</small>${M(amt)}</div>${L.ab(t('Pay now','ادفع الآن'),'paynow',null,{dis:!sel.length})}`}; }});
