ACT.paynow=()=>{ const s=S(); const sel=s.invoices.filter(i=>bal(i)>0&&L.ui.paySel&&L.ui.paySel[i.no]); if(!sel.length){ toast(t('Choose at least one invoice','اختر فاتورة واحدة على الأقل')); return; } const amt=r2(sel.reduce((a,i)=>a+bal(i),0));
 const done=()=>{ const id='RC-2026-0'+(++s.seq.pay); sel.forEach(i=>{ i.paid=r2((i.paid||0)+bal(i)); }); s.payments.unshift({id,ts:now(),amt,m:L.ui.payM,inv:sel.map(i=>i.no)}); L.ui.paySel={}; L.notify('wallet',[`Payment ${id} received · ${amt.toFixed(2)}`,`استُلمت الدفعة ${id} · ${amt.toFixed(2)}`],['b.receipt',{id}]); L.save(); go('b.receipt',{id}); setTimeout(()=>toast(t('Payment received · thank you','استُلمت الدفعة · شكرًا')),80); };
 if(L.ui.payM==='card') L.cardSheet(amt,done,t(`${sel.length} invoice(s)`,`${sel.length} فاتورة`)); else done(); };
