L.def('b.statement',{render:(c)=>{ const s=S(); const ev=[]; s.invoices.forEach(i=>{ if(invX(i)) return; const a=invAmt(i); if(a==null) return; ev.push({ts:i.d,t:LTR(i.no),d:a}); }); s.payments.forEach(p=>ev.push({ts:p.ts,t:t('Payment','دفعة')+' '+LTR(p.id),d:-p.amt})); s.cns.forEach(n=>ev.push({ts:n.ts,t:t('Credit note','إشعار دائن')+' '+LTR(n.no),d:-n.amt})); ev.sort((a,b)=>a.ts-b.ts); let run=0; const rows=ev.map(e=>{ run=r2(run+e.d); return [dt(e.ts),e.t,M(e.d),M(run)]; });
 const ag={cur:0,a:0,b:0,c:0}; s.invoices.forEach(i=>{ const b=bal(i); if(b<=0) return; const late=Math.floor((now()-i.due)/DAY); if(late<=0) ag.cur+=b; else if(late<=30) ag.a+=b; else if(late<=60) ag.b+=b; else ag.c+=b; });
 return H.kpis([[t('Current','جارية'),M(ag.cur)],[t('1–30 days','1–30 يومًا'),M(ag.a),'',ag.a?'warn':''],[t('31–60 days','31–60 يومًا'),M(ag.b),'',ag.b?'bad':''],[t('60+ days','60+ يومًا'),M(ag.c)]])+H.sec(t('Account activity','حركة الحساب'),H.table([t('Date','التاريخ'),t('Item','البند'),t('Amount','المبلغ'),t('Balance','الرصيد')],rows,t('Statement','الكشف')),{raw:true})+H.btns(L.ab(t('Download statement','نزّل الكشف'),'pdf','st',{k:'sec',ic:'download'}),H.btn(t('Pay invoices','ادفع الفواتير'),{go:'b.pay'})); }});
