L.def('b.credit',{v:null,noSeg:true,render:(c)=>{ const s=S(), cr=credit(); let h=H.sec('',`<div class="card pad">${H.hero(t('Available credit','الائتمان المتاح'),M(cr.avail),t('of','من')+' '+M(cr.limit,'',0)+' · '+t('used','مستخدم')+' '+M(cr.used))}${H.meter([[cr.used/cr.limit*100,cr.hold?'danger':'brand']],t(`Used ${Math.round(cr.used/cr.limit*100)}%`,`مستخدم ${Math.round(cr.used/cr.limit*100)}%`))}</div>`,{raw:true});
 if(cr.overdue) h+=H.alert(cr.hold?'bad':'warn',cr.hold?t('Credit on hold','الائتمان موقوف'):t('Overdue balance','رصيد متأخر'),M(cr.overdue)+' · '+t(`${cr.late} days late. Paying releases any hold instantly.`,`متأخر ${cr.late} أيام. السداد يعيد التفعيل فورًا.`),{act:H.btn(t('Pay now','ادفع الآن'),{sm:true,go:'b.pay'})});
 h+=H.sec(t('Credit requests','طلبات الائتمان'),s.apps.some(a=>a.by==='owner')?H.rows(s.apps.filter(a=>a.by==='owner').map(a=>({ic:'shield',tone:'brand',t:`${LTR(a.id)} · +${M(a.amt,'',0)}`,s:dt(a.ts),pill:L.appPill(a),go:'b.creditStatus',q:{id:a.id}}))):`<div style="padding:8px 0">${H.note(t('Need more room? Ask for an increase — up to 10,000 is decided by an accountant; above that a manager approves too.','تحتاج مساحة أكبر؟ اطلب زيادة — حتى 10,000 يقررها المحاسب، وما فوق ذلك يعتمده المدير أيضًا.'))}</div>`);
 h+=H.sec('',H.rows([{ic:'doc',tone:'brand',t:t('Statement & aging','الكشف وأعمار الديون'),go:'b.statement'},{ic:'info',tone:'brand',t:t('How reminders & holds work','كيف تعمل التذكيرات والإيقاف'),go:'b.hold'}]));
 return {b:h,dock:c.role==='owner'?H.btn(t('Request more credit','اطلب ائتمانًا إضافيًا'),{go:'b.creditApp',ic:'plus'}):''}; }});
L.def('b.creditApp',{v:null,noSeg:true,t:['Request more credit','طلب ائتمان إضافي'],render:(c)=>{ const cr=credit(); return H.sec('',`<div style="padding:14px 16px">${L.fld('camt',t('Additional credit (SAR)','الائتمان الإضافي (ريال)'),{req:true,pre:'SAR',im:'decimal',ltr:true,val:'',ph:'5000',hint:t(`Current limit ${(cr.limit==null?'—':cr.limit.toLocaleString('en-US'))}. Up to 10,000: accountant decides. Above: accountant, then manager.`,`الحد الحالي ${(cr.limit==null?'—':cr.limit.toLocaleString('en-US'))}. حتى 10,000: يقرر المحاسب. أكثر: المحاسب ثم المدير.`)})}${L.fld('cwhy',t('Reason','السبب'),{sel:[['season',t('Seasonal peak (e.g. Ramadan)','موسم ذروة (مثل رمضان)')],['branch',t('New branch','فرع جديد')],['growth',t('Business growth','نمو الأعمال')],['other',t('Other','أخرى')]],val:'season'})}${L.fld('cbuy',t('Average monthly purchases (SAR)','متوسط المشتريات الشهرية (ريال)'),{pre:'SAR',im:'decimal',ltr:true,val:'12000'})}${L.fld('cnote',t('Anything else? (optional)','أي شيء آخر؟ (اختياري)'),{ta:true})}</div>`)+H.sec('',L.check('ccons',t('I agree to a credit check (sample consent)','أوافق على الاستعلام الائتماني (موافقة تجريبية)'),false,t('No real credit bureau is contacted in this preview.','لا يتم التواصل مع أي جهة ائتمانية حقيقية.')))+H.btns(L.ab(t('Submit request','أرسل الطلب'),'capp')); }});
