ACT.capp=()=>{ L.clearBad(); const amt=Number(String(L.val('camt')).replace(/[, ]/g,'')); let ok=true; if(!amt||amt<500){ L.bad('camt',t('Enter an amount of at least 500','أدخل مبلغًا لا يقل عن 500')); ok=false; } else if(amt>100000){ L.bad('camt',t('Maximum in this preview is 100,000','الحد الأقصى في هذه النسخة 100,000')); ok=false; } if(!L.val('ccons')){ L.bad('ccons',t('Please agree to the credit check','يرجى الموافقة على الاستعلام')); ok=false; } if(!ok){ L.focusBad(); toast(t('Check the highlighted fields','راجع الحقول المحددة')); return; }
 const s=S(); const id='CA-2026-0'+(++s.seq.app); s.apps.unshift({id,ts:now(),by:'owner',cust:['Al Wadi Restaurant','مطعم الوادي'],amt,why:L.val('cwhy'),buy:Number(L.val('cbuy'))||0,note:L.val('cnote'),st:'acct',route:amt<=10000?'acct':'mgr',log:[{ts:now(),who:'owner',k:'submit'}]}); L.notify('shield',[`Credit request ${id} submitted`,`أُرسل طلب الائتمان ${id}`],['b.creditStatus',{id}]); L.save(); go('b.creditStatus',{id}); setTimeout(()=>toast(t('Request submitted','أُرسل الطلب')),80); };
L.def('b.creditStatus',{v:null,noSeg:true,t:['Credit request status','حالة طلب الائتمان'],render:(c)=>{ const id=qp('id'); const a=S().apps.find(x=>x.id===id)||S().apps.find(x=>x.by==='owner'); if(!a) return H.empty('shield',t('No credit requests','لا طلبات ائتمان'),t('Submit one from Credit.','أرسل طلبًا من الائتمان.'),H.btns(H.btn(t('Request more credit','اطلب ائتمانًا'),{go:'b.creditApp'})));
 const big=a.route==='mgr'; const p=L.appPill(a); const lg=k=>a.log.find(l=>l.k===k);
 const steps=[['done',t('Submitted','أُرسل'),dt(a.ts,{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})],[a.st==='acct'?'now':lg('acct-no')?'hold':'done',t('Accountant review','مراجعة المحاسب'),t('Noura · credit desk','نورة · مكتب الائتمان')]];
 if(big) steps.push([a.st==='mgr'?'now':a.st==='approved'?'done':lg('mgr-no')?'hold':'next',t('Manager approval (over 10,000)','اعتماد المدير (أكثر من 10,000)'),t('Saad · credit committee','سعد · لجنة الائتمان')]);
 steps.push([a.st==='approved'?'done':a.st==='declined'?'hold':'next',a.st==='declined'?t('Declined','مرفوض'):t('New limit active','الحد الجديد فعّال'),'']);
 let h=H.sec('',`<div class="card pad">${H.hero(LTR(a.id),'+'+M(a.amt,'',0),big?t('Route: accountant → manager','المسار: المحاسب ← المدير'):t('Route: accountant','المسار: المحاسب'))}<p style="margin-top:8px">${H.pill(p[0],p[1])}</p></div>`,{raw:true})+H.sec(t('Progress','التقدم'),H.tl(steps));
 if(a.st==='approved') h+=H.alert('ok',t('Approved · new limit active','معتمد · الحد الجديد فعّال'),t('Your limit is now','حدك الآن')+' '+M(S().credit.limit,'',0),{role:'status'});
 if(a.st==='declined') h+=H.alert('bad',t('Not approved this time','لم يُعتمد هذه المرة'),esc(T2(a.reason||['You can ask again in 30 days.','يمكنك الطلب مجددًا بعد 30 يومًا.'])));
 if((a.st==='acct'||a.st==='mgr')&&MF.ROLES[c.role].grp==='customer') h+=H.alert('info',t('Try the approval side','جرّب جانب الاعتماد'),a.st==='acct'?t('Sign in as the accountant to review it.','ادخل كمحاسب لمراجعته.'):t('Sign in as the manager to approve it.','ادخل كمدير لاعتماده.'),{act:L.ab(a.st==='acct'?t('Switch to accountant','بدّل إلى المحاسب'):t('Switch to manager','بدّل إلى المدير'),'login',a.st==='acct'?'acct':'mgr',{sm:true,k:'sec'})});
 return h; }});

